-- ----------------------------
-- Table structure for conf_sys_safe
-- ----------------------------
DROP TABLE IF EXISTS `conf_sys_safe`;
CREATE TABLE `conf_sys_safe`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `login_client` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '登录允许客户端',
  `login_retry` int NULL DEFAULT 0 COMMENT '登录失败重试次数',
  `login_cap` int NULL DEFAULT 0 COMMENT '登录验证码',
  `login_mfa` int NULL DEFAULT 0 COMMENT '登录多因素认证',
  `pass_update` int NULL DEFAULT 0 COMMENT '密码定期更新',
  `pass_check` int NULL DEFAULT 0 COMMENT '密码强度校验',
  `pass_length` int NULL DEFAULT 0 COMMENT '密码长度校验',
  `pass_num` int NULL DEFAULT 0 COMMENT '密码数字校验',
  `pass_l_char` int NULL DEFAULT 0 COMMENT '密码小写字母校验',
  `pass_u_char` int NULL DEFAULT 0 COMMENT '密码大写字母校验',
  `pass_s_char` int NULL DEFAULT 0 COMMENT '密码特殊字母校验',
  `pass_reset_sms` int NULL DEFAULT NULL COMMENT '密码重置短信验证',
  `create_user_id` bigint NULL DEFAULT NULL COMMENT '创建者ID',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_user_id` bigint NULL DEFAULT NULL COMMENT '更新者ID',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `scope_user_id` bigint NULL DEFAULT NULL COMMENT '数据权限用户ID',
  `scope_org_id` bigint NULL DEFAULT NULL COMMENT '数据权限机构ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `scope_org_id`(`scope_org_id` ASC) USING BTREE COMMENT '权限组织索引',
  INDEX `scope_user_id`(`scope_user_id` ASC) USING BTREE COMMENT '权限用户索引'
) ENGINE = InnoDB AUTO_INCREMENT = 1915642857616097283 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '配置安全性表' ROW_FORMAT = DYNAMIC;

