  `check_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '校验码',
  `nick_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账户昵称',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '头像地址',
  `source_flag` tinyint(1) NULL DEFAULT 0 COMMENT '用户类型（SourceFlagEnum）',
  `account_flag` tinyint(1) NULL DEFAULT NULL COMMENT '帐号状态（AccountFlagEnum）',
  `preview_flag` tinyint(1) NULL DEFAULT NULL COMMENT '预览模式（YesOrNoEnum）',
  `del_flag` tinyint(1) NULL DEFAULT 0 COMMENT '删除标志（YesOrNoEnum）',
  `login_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最后登陆IP',
